namespace CodeLearn.Helpers
{
    public static class AvatarHelper
    {
        /// <summary>
        /// Returns the avatar URL for a user.
        /// If the user has a custom avatar, returns it as-is.
        /// Otherwise returns a pixel letter-avatar generated by /Account/LetterAvatar.
        /// </summary>
        public static string GetUrl(string? nick, string? avatarUrl)
        {
            if (!string.IsNullOrEmpty(avatarUrl)) return avatarUrl;
            var n = string.IsNullOrWhiteSpace(nick) ? "?" : nick;
            return "/Account/LetterAvatar?nick=" + Uri.EscapeDataString(n);
        }
    }
}
